<script>
(()=>{'use strict';
 const API='./api/rr',DATE_API='./api/date/',KODE_API='./api/kode/',OTP_HEAD=<?=json_encode($thead,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,CCL_HEAD=<?=json_encode($cclThead,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,ICON_DOWNLOAD=<?=json_encode(mb_svg('download'),JSON_UNESCAPED_SLASHES)?>,ICON_LOCK=<?=json_encode(mb_svg('lock'),JSON_UNESCAPED_SLASHES)?>;
 const state={view:'otp',rows:[],total:{},sort:{column:'tgl',direction:'asc'},userCode:'000',detail:[],detailPage:1,detailPages:1,detailTotal:0,detailType:'detail_rr',detailStatus:'ALL',detailDate:'ALL',detailCollectionStatus:'ALL',detailScope:{},detailTimer:null,abort:null};
 const el=id=>document.getElementById(id),ui=()=>window.MonbisUI||{},num=v=>Number(v||0),fmt=v=>ui().fmt?ui().fmt(v):new Intl.NumberFormat('id-ID').format(num(v)),esc=v=>ui().escape?ui().escape(v):String(v??'');
 const post=async(url,body,signal)=>{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal}),j=await r.json();if(!r.ok||Number(j.status)!==200)throw new Error(j.message||'Gagal memuat data');return j};
 const currentUser=()=>window.getUser?.()||{};
 const resolveUserCode=()=>{const raw=currentUser().kode_kantor||currentUser().kode||currentUser().kode_cabang||'000',code=String(raw).replace(/\D/g,'').padStart(3,'0').slice(-3);return code==='099'?'000':code};
 const selectedText=id=>el(id)?.selectedOptions?.[0]?.textContent||'';
 const statusLabel=s=>({ALL:'Semua Target',LANCAR:'OTP Lancar',MENUNGGAK:'Ditagih',ANGSURAN:'Angsuran',LEWAT_TAGIH:'Angsuran Lewat JT',SESUAI_TAGIH:'Angsuran Sesuai JT',TOTAL_BAYAR:'Total Run Off',LUNAS:'Lunas'})[s]||s;
 const pctTone=v=>num(v)>=85?'mb-pill--success':num(v)>=60?'mb-pill--amber':'mb-pill--danger';
 function payload(extra={}){const office=el('reportOtpOffice').value,sub=el('reportOtpSub').value;return{closing_date:el('reportOtpClosing').value,harian_date:el('reportOtpActual').value,kode_kantor:office||null,korwil:office?'':sub,kode_kankas:office?sub:'',kode_ao:el('reportOtpAo').value||'',dpd_bucket:el('reportOtpDpd').value,include_127:el('reportOtpKpp').checked,...extra}}
 function metric(r,value,noa,status,tone,dateValue,type='detail_rr',sub=''){const content='<span class="mb-potensi-metric__value">'+fmt(r[value])+'</span><span class="mb-subvalue">'+(sub||fmt(r[noa]||0)+' NOA')+'</span>';return '<button type="button" class="mb-potensi-metric mb-potensi-metric--'+tone+'" data-otp-detail="'+esc(status)+'" data-otp-date="'+esc(dateValue)+'" data-otp-type="'+type+'">'+content+'</button>'}
 function row(r,total=false){const d=total?'ALL':String(r.tgl).padStart(2,'0'),klass=total?' class="mb-total-row"':'';return '<tr'+klass+'><td class="mb-code-col mb-sticky-left mb-code">'+(total?'TOTAL':d)+'</td><td class="mb-num">'+metric(r,'target_os','target_noa','ALL','blue',d)+'</td><td class="mb-num">'+metric(r,'lancar_os','lancar_noa','LANCAR','green',d)+'</td><td class="mb-num">'+metric(r,'macet_os','macet_noa','MENUNGGAK','red',d)+'</td><td class="mb-num">'+metric(r,'lunas_os','lunas_noa','LUNAS','green',d,'detail_lunas_rr')+'</td><td class="mb-num">'+metric(r,'angsuran_lewat','angsuran_lewat_noa','LEWAT_TAGIH','red',d,'detail_rr',fmt(r.angsuran_lewat_noa||0)+' NOA · '+num(r.angsuran_lewat_persen).toFixed(2)+'%')+'</td><td class="mb-num">'+metric(r,'angsuran_sesuai','angsuran_sesuai_noa','SESUAI_TAGIH','green',d,'detail_rr',fmt(r.angsuran_sesuai_noa||0)+' NOA · '+num(r.angsuran_sesuai_persen).toFixed(2)+'%')+'</td><td class="mb-num">'+metric(r,'angsuran','angsuran_sesuai_noa','ANGSURAN','amber',d,'detail_rr','Total angsuran')+'</td><td class="mb-num mb-cyan">'+metric(r,'total_bayar','target_noa','TOTAL_BAYAR','blue',d,'detail_rr','Pencapaian')+'</td><td class="mb-text-center"><span class="mb-pill '+pctTone(r.persen)+'">'+num(r.persen).toFixed(2)+'%</span></td></tr>'}
 function cclMetric(value,status,area,sub=''){return '<button type="button" class="mb-ccl-detail-link" data-ccl-detail="'+esc(status)+'" data-ccl-area="'+esc(area)+'">'+fmt(value)+(sub?'<span class="mb-subvalue">'+esc(sub)+'</span>':'')+'</button>'}
 function cclRow(r,total=false){const code=total?'ALL':r.kode_area||'-',area=total?'TOTAL':r.kode_area||'',klass=total?' class="mb-total-row"':'';return '<tr'+klass+'><td class="mb-code-col mb-sticky-left mb-code">'+esc(code)+'</td><td class="mb-sticky-left-2 mb-name" style="--mb-sticky-1:52px">'+esc(total?'GRAND TOTAL':r.nama_area||'-')+'</td><td class="mb-noa mb-blue">'+cclMetric(r.target_noa,'ALL',area)+'</td><td class="mb-noa mb-cyan">'+cclMetric(r.call_noa,'CALL',area,fmt(r.call_frekuensi)+' kali')+'</td><td class="mb-text-center"><span class="mb-pill '+pctTone(r.call_percent)+'">'+num(r.call_percent).toFixed(2)+'%</span></td><td class="mb-noa mb-negative">'+cclMetric(r.nc_noa,'NC',area)+'</td><td class="mb-num mb-negative">'+cclMetric(r.nc_os,'NC',area)+'</td><td class="mb-noa mb-amber">'+cclMetric(r.ptp_noa,'PTP',area)+'</td><td class="mb-num mb-amber">'+cclMetric(r.ptp_os,'PTP',area)+'</td><td class="mb-noa mb-positive">'+cclMetric(r.po_noa,'PO',area)+'</td><td class="mb-num mb-positive">'+cclMetric(r.po_os,'PO',area)+'</td><td class="mb-num mb-blue">'+cclMetric(r.po_bayar,'PO',area)+'</td></tr>'}
 function filtered(){const dir=state.sort.direction==='asc'?1:-1;return [...state.rows].sort((a,b)=>{const c=state.sort.column;return Number.isFinite(Number(a[c]))&&a[c]!==''?(num(a[c])-num(b[c]))*dir:String(a[c]||'').localeCompare(String(b[c]||''),'id-ID',{numeric:true})*dir})}
 function syncView(){const table=el('reportOtpTable'),title=table.closest('.mb-report-card').querySelector('.mb-report-toolbar__title'),button=el('reportOtpViewSwitch'),isCcl=state.view==='ccl';table.querySelector('thead').innerHTML=isCcl?CCL_HEAD:OTP_HEAD;table.classList.toggle('mb-otp-ccl-table',isCcl);title.textContent=isCcl?'Rekap CCL':'Rekap OTP per Tanggal';button.innerHTML=isCcl?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5M11 18l-6-6 6-6"/></svg>':ICON_LOCK;button.title=isCcl?'Kembali ke OTP':'Buka Rekap CCL';button.setAttribute('aria-label',button.title)}
 function render(){syncView();const isCcl=state.view==='ccl',renderRow=isCcl?cclRow:row,cols=isCcl?12:10;el('reportOtpTotal').innerHTML=Object.keys(state.total||{}).length?renderRow(state.total,true):'';const rows=filtered();el('reportOtpBody').innerHTML=rows.length?rows.map(r=>renderRow(r)).join(''):'<tr><td colspan="'+cols+'" class="mb-empty">Data '+(isCcl?'CCL':'OTP')+' tidak ditemukan.</td></tr>'}
 async function load(){if(state.abort)state.abort.abort();state.abort=new AbortController();ui().showLoading?.('reportOtpLoading',true);try{const type=state.view==='ccl'?'rekap_rr_collection_area':'rekap_rr',j=await post(API,payload({type,collection_status:'ALL',page:1,limit:100}),state.abort.signal);state.rows=j.data?.data||[];state.total=state.view==='ccl'?(j.data?.summary||{}):(j.data?.grand_total||{});state.sort={column:state.view==='ccl'?'kode_area':'tgl',direction:'asc'};render();ui().closeMobileFilter?.('reportOtpHeaderFilters')}catch(e){if(e.name!=='AbortError'){console.error(e);state.rows=[];state.total={};render()}}finally{ui().showLoading?.('reportOtpLoading',false)}}
 async function loadSubAndAo(reload=true){const office=el('reportOtpOffice').value,sub=el('reportOtpSub'),ao=el('reportOtpAo');if(!office){sub.previousElementSibling.textContent='Korwil';sub.innerHTML='<option value="">Semua Korwil</option><option value="SEMARANG">Semarang</option><option value="SOLO">Solo</option><option value="BANYUMAS">Banyumas</option><option value="PEKALONGAN">Pekalongan</option>';ao.innerHTML='<option value="">Pilih cabang dulu</option>';ao.disabled=true}else{sub.previousElementSibling.textContent='Kankas';ao.disabled=false;const [k,a]=await Promise.all([post(KODE_API,{type:'kode_kankas',kode_kantor:office}).catch(()=>({data:[]})),post(KODE_API,{type:'kode_ao_kredit',kode_kantor:office}).catch(()=>({data:[]}))]);sub.innerHTML='<option value="">Semua Kankas</option>'+((k.data||[]).map(x=>'<option value="'+esc(x.kode_group1)+'">'+esc(x.deskripsi_group1||x.kode_group1)+'</option>').join(''));ao.innerHTML='<option value="">Semua AO</option>'+((a.data||[]).map(x=>'<option value="'+esc(x.kode_group2)+'">'+esc(x.nama_ao||x.kode_group2)+'</option>').join(''))}if(reload)load()}
 async function initFilters(){const [d,k]=await Promise.all([fetch(DATE_API).then(r=>r.json()),post(KODE_API,{type:'kode_kantor'})]);el('reportOtpClosing').value=d.data?.last_closing||'';el('reportOtpActual').value=d.data?.last_created||'';state.userCode=resolveUserCode();const offices=k.data||[],office=el('reportOtpOffice');if(state.userCode!=='000'){const own=offices.find(x=>String(x.kode_kantor).padStart(3,'0')===state.userCode);office.innerHTML='<option value="'+state.userCode+'">'+state.userCode+' - '+esc(own?.nama_kantor||'Cabang')+'</option>';office.disabled=true}else office.innerHTML='<option value="">Konsolidasi</option>'+offices.filter(x=>String(x.kode_kantor).padStart(3,'0')!=='000').map(x=>'<option value="'+esc(String(x.kode_kantor).padStart(3,'0'))+'">'+esc(String(x.kode_kantor).padStart(3,'0')+' - '+x.nama_kantor)+'</option>').join('');await loadSubAndAo(false)}
 function detailSummary(rows){const box=el('reportOtpDetailSummary'),os=rows.reduce((s,r)=>s+num(r.os_curr||r.os_lunas),0),bayar=rows.reduce((s,r)=>s+num(r.trx_bulan_ini),0),tab=rows.reduce((s,r)=>s+num(r.tabungan),0);box.classList.remove('is-hidden');box.innerHTML='<div class="mb-summary-card mb-summary-card--blue"><div class="mb-summary-card__label">Debitur</div><div class="mb-summary-card__value">'+fmt(state.detailTotal)+' NOA</div></div><div class="mb-summary-card mb-summary-card--amber"><div class="mb-summary-card__label">BD Halaman</div><div class="mb-summary-card__value">Rp '+fmt(os)+'</div></div><div class="mb-summary-card mb-summary-card--green"><div class="mb-summary-card__label">Bayar Halaman</div><div class="mb-summary-card__value">Rp '+fmt(bayar)+'</div></div><div class="mb-summary-card"><div class="mb-summary-card__label">Saldo Tab Halaman</div><div class="mb-summary-card__value">Rp '+fmt(tab)+'</div></div>'}
 function renderDetail(){const rows=state.detail,lunas=state.detailType==='detail_lunas_rr';detailSummary(rows);if(lunas){el('reportOtpDetailBody').innerHTML='<table class="mb-table mb-detail-mini mb-otp-detail-table"><thead><tr><th class="mb-sticky-left">Rekening</th><th class="mb-sticky-left-2 mb-text-left">Nasabah / Alamat</th><th>Status</th><th>AO / Kankas</th><th>Plafon Lama</th><th>OS Lunas</th><th>Rekening Baru</th><th>Plafond Baru</th></tr></thead><tbody>'+(!rows.length?'<tr><td colspan="8" class="mb-empty">Detail tidak ditemukan.</td></tr>':rows.map(r=>'<tr><td class="mb-sticky-left mb-code">'+esc(r.no_rekening||'-')+'</td><td class="mb-sticky-left-2 mb-name">'+esc(r.nama_nasabah||'-')+'<span class="mb-subvalue">'+esc(r.alamat||'-')+'</span></td><td class="mb-text-center"><span class="mb-pill mb-pill--success">'+esc(r.status_lunas||'LUNAS')+'</span></td><td>'+esc(r.nama_ao||'-')+'<span class="mb-subvalue">'+esc(r.kankas||'-')+'</span></td><td class="mb-num">'+fmt(r.plafon_lama)+'</td><td class="mb-num mb-positive">'+fmt(r.os_lunas)+'</td><td class="mb-code">'+esc(r.rek_baru||'-')+'</td><td class="mb-num mb-blue">'+fmt(r.plafond_baru)+'</td></tr>').join(''))+'</tbody></table>';el('reportOtpDetailMobile').innerHTML=rows.map(r=>'<article class="mb-detail-card"><div class="mb-detail-card__head"><div class="mb-detail-card__identity"><div class="mb-detail-card__name">'+esc(r.nama_nasabah||'-')+'</div><div class="mb-detail-card__meta">'+esc(r.no_rekening||'-')+'</div></div><span class="mb-pill mb-pill--success">'+esc(r.status_lunas||'LUNAS')+'</span></div><div class="mb-detail-card__address"><span>Alamat</span><strong>'+esc(r.alamat||'-')+'</strong></div><div class="mb-detail-card__metrics"><div class="mb-detail-card__metric"><span>OS Lunas</span><strong>Rp '+fmt(r.os_lunas)+'</strong></div><div class="mb-detail-card__metric"><span>Plafon Lama</span><strong>Rp '+fmt(r.plafon_lama)+'</strong></div><div class="mb-detail-card__metric"><span>Rekening Baru</span><strong>'+esc(r.rek_baru||'-')+'</strong></div><div class="mb-detail-card__metric"><span>Plafond Baru</span><strong>Rp '+fmt(r.plafond_baru)+'</strong></div></div></article>').join('')}else{el('reportOtpDetailBody').innerHTML='<table class="mb-table mb-detail-mini mb-otp-detail-table"><thead><tr><th class="mb-sticky-left">Rekening</th><th class="mb-sticky-left-2 mb-text-left">Nasabah / Alamat</th><th>Status</th><th>AO / Kankas</th><th>BD M-1</th><th>BD Act</th><th>DPD</th><th>Tunggakan</th><th>Saldo Tab</th><th>Bayar</th><th>Tgl Bayar</th></tr></thead><tbody>'+(!rows.length?'<tr><td colspan="11" class="mb-empty">Detail tidak ditemukan.</td></tr>':rows.map(r=>'<tr><td class="mb-sticky-left mb-code">'+esc(r.no_rekening||'-')+'</td><td class="mb-sticky-left-2 mb-name">'+esc(r.nama_nasabah||'-')+'<span class="mb-subvalue">'+esc(r.alamat||'-')+'</span></td><td class="mb-text-center"><span class="mb-pill '+(r.collection_status==='PO'?'mb-pill--success':r.collection_status==='PTP'?'mb-pill--amber':'mb-pill--danger')+'">'+esc(r.collection_status||r.status_ket||'-')+'</span><span class="mb-subvalue">'+esc(r.status_pembayaran||'-')+'</span></td><td>'+esc(r.nama_ao||'-')+'<span class="mb-subvalue">'+esc(r.kankas||'-')+'</span></td><td class="mb-num">'+fmt(r.os_m1)+'</td><td class="mb-num mb-blue">'+fmt(r.os_curr)+'</td><td class="mb-text-center">'+fmt(r.dpd_curr)+'</td><td class="mb-num mb-negative">'+fmt(r.totung)+'</td><td class="mb-num mb-positive">'+fmt(r.tabungan)+'</td><td class="mb-num mb-positive">'+fmt(r.trx_bulan_ini)+'</td><td class="mb-text-center">'+esc(r.tgl_bayar_ini||'-')+'</td></tr>').join(''))+'</tbody></table>';el('reportOtpDetailMobile').innerHTML=rows.map(r=>'<article class="mb-detail-card"><div class="mb-detail-card__head"><div class="mb-detail-card__identity"><div class="mb-detail-card__name">'+esc(r.nama_nasabah||'-')+'</div><div class="mb-detail-card__meta">'+esc(r.no_rekening||'-')+' · '+esc(r.kankas||'-')+'</div></div><span class="mb-pill '+(r.collection_status==='PO'?'mb-pill--success':r.collection_status==='PTP'?'mb-pill--amber':'mb-pill--danger')+'">'+esc(r.collection_status||'-')+'</span></div><div class="mb-detail-card__address"><span>Alamat</span><strong>'+esc(r.alamat||'-')+'</strong></div><div class="mb-detail-card__metrics"><div class="mb-detail-card__metric"><span>BD M-1 / Act</span><strong>Rp '+fmt(r.os_m1)+' / '+fmt(r.os_curr)+'</strong></div><div class="mb-detail-card__metric"><span>DPD / Tunggakan</span><strong>'+fmt(r.dpd_curr)+' / Rp '+fmt(r.totung)+'</strong></div><div class="mb-detail-card__metric"><span>Saldo Tabungan</span><strong>Rp '+fmt(r.tabungan)+'</strong></div><div class="mb-detail-card__metric"><span>Bayar Bulan Ini</span><strong>Rp '+fmt(r.trx_bulan_ini)+'</strong><small>'+esc(r.tgl_bayar_ini||r.status_pembayaran||'-')+'</small></div></div></article>').join('')}const footer=el('reportOtpDetailFooter');footer.classList.toggle('is-hidden',!state.detailTotal);footer.innerHTML=!state.detailTotal?'':'<div class="mb-detail-page-info">'+fmt(state.detailTotal)+' data</div><div class="mb-detail-page-actions"><span class="mb-detail-footer-actions"><button type="button" id="reportOtpDetailExport" class="mb-detail-footer-icon mb-detail-footer-icon--export" title="Export detail">'+ICON_DOWNLOAD+'</button></span><span class="mb-detail-pagination"><button type="button" class="mb-detail-page-btn" data-detail-page="prev" '+(state.detailPage<=1?'disabled':'')+'>&lsaquo; Prev</button><span class="mb-detail-page-status">Hal '+state.detailPage+' / '+state.detailPages+'</span><button type="button" class="mb-detail-page-btn" data-detail-page="next" '+(state.detailPage>=state.detailPages?'disabled':'')+'>Next &rsaquo;</button></span></div>'}
 async function loadDetail(page=1){state.detailPage=page;ui().showLoading?.('reportOtpDetailLoading',true);try{const j=await post(API,payload({type:state.detailType,tgl_tagih:state.detailDate,status:state.detailStatus,collection_status:state.detailCollectionStatus,limit:20,page,search:el('reportOtpDetailSearch').value||'',...state.detailScope}));state.detail=j.data?.data||[];const p=j.data?.pagination||{};state.detailTotal=num(p.total_records||state.detail.length);state.detailPages=Math.max(1,num(p.total_pages||1));renderDetail()}catch(e){console.error(e);state.detail=[];state.detailTotal=0;state.detailPages=1;renderDetail()}finally{ui().showLoading?.('reportOtpDetailLoading',false)}}
 function openDetail(button){state.detailType=button.dataset.otpType||'detail_rr';state.detailStatus=button.dataset.otpDetail||'ALL';state.detailDate=button.dataset.otpDate||'ALL';state.detailCollectionStatus='ALL';state.detailScope={};el('reportOtpDetailSearch').value='';el('reportOtpDetailTitle').textContent=statusLabel(state.detailStatus);el('reportOtpDetailSubtitle').textContent='Tanggal tagih '+state.detailDate+' · '+selectedText('reportOtpDpd');ui().openModal?.('reportOtpDetail');loadDetail(1)}
 function openCollectionDetail(button){const area=String(button.dataset.cclArea||'TOTAL'),status=String(button.dataset.cclDetail||'ALL').toUpperCase(),office=el('reportOtpOffice').value,isTotal=area==='TOTAL'||area==='';state.detailType='detail_rr';state.detailStatus='ALL';state.detailDate='ALL';state.detailCollectionStatus=['ALL','CALL','NC','PTP','PO'].includes(status)?status:'ALL';state.detailScope={};if(!isTotal)state.detailScope=office?{kode_kankas:area}:{kode_kantor:area,korwil:'',kode_kankas:''};el('reportOtpDetailSearch').value='';const labels={ALL:'Target Collection',CALL:'Sudah Dihubungi',NC:'NC · No Contact',PTP:'PTP · Promise To Pay',PO:'PO · Paid Off'};el('reportOtpDetailTitle').textContent='Detail CCL '+(labels[state.detailCollectionStatus]||state.detailCollectionStatus);el('reportOtpDetailSubtitle').textContent=(isTotal?'Semua area':area)+' · '+selectedText('reportOtpDpd');ui().openModal?.('reportOtpDetail');loadDetail(1)}
 function bindCollectionDetail(){el('reportOtpTable').addEventListener('click',e=>{const button=e.target.closest('[data-ccl-detail]');if(button&&state.view==='ccl')openCollectionDetail(button)})}
 function exportTsv(rows,name){if(!rows.length)return;const keys=Object.keys(rows[0]),lines=[keys.join('\t'),...rows.map(r=>keys.map(k=>String(r[k]??'').replace(/[\t\r\n]+/g,' ')).join('\t'))],blob=new Blob(['\ufeff'+lines.join('\n')],{type:'application/vnd.ms-excel;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name+'.xls';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
 const CCL_ACCESS_CODE='ccl2026',CCL_ACCESS_KEY='report_otp_ccl_access_v1';
 const hasCclAccess=()=>{try{return sessionStorage.getItem(CCL_ACCESS_KEY)==='1'}catch(e){return window.__reportOtpCclAccess===true}};
 function setView(view){state.view=view==='ccl'?'ccl':'otp';load()}
 function requestCcl(){if(hasCclAccess())return setView('ccl');el('reportOtpAccessInput').value='';el('reportOtpAccessError').textContent='';ui().openModal?.('reportOtpAccess');setTimeout(()=>el('reportOtpAccessInput').focus(),80)}
 function submitAccess(e){e.preventDefault();const input=el('reportOtpAccessInput'),error=el('reportOtpAccessError');if(String(input.value||'').trim()!==CCL_ACCESS_CODE){error.textContent='Kode akses tidak sesuai. Silakan periksa kembali.';input.select();input.focus();return}try{sessionStorage.setItem(CCL_ACCESS_KEY,'1')}catch(x){window.__reportOtpCclAccess=true}error.textContent='';ui().closeModal?.('reportOtpAccess');setView('ccl')}
 function toggleAccessInput(button){const input=el(button.dataset.mbAccessToggle);if(!input)return;const visible=input.type==='password';input.type=visible?'text':'password';button.setAttribute('aria-label',visible?'Sembunyikan kode':'Tampilkan kode');input.focus()}
 function bind(){['reportOtpClosing','reportOtpActual','reportOtpSub','reportOtpDpd','reportOtpAo','reportOtpKpp'].forEach(id=>el(id).addEventListener('change',load));el('reportOtpOffice').addEventListener('change',()=>loadSubAndAo(true));el('reportOtpSearch').addEventListener('input',ui().debounce?ui().debounce(render,120):render);el('reportOtpViewSwitch').addEventListener('click',()=>state.view==='ccl'?setView('otp'):requestCcl());el('reportOtpAccessForm').addEventListener('submit',submitAccess);el('reportOtpAccess').addEventListener('click',e=>{const toggle=e.target.closest('[data-mb-access-toggle]');if(toggle)toggleAccessInput(toggle)});el('reportOtpExport').addEventListener('click',()=>exportTsv([{...(state.view==='ccl'?{kode_area:'ALL',nama_area:'GRAND TOTAL'}:{tgl:'TOTAL'}),...state.total},...filtered()],state.view==='ccl'?'Rekap_CCL':'Report_OTP'));el('reportOtpTable').addEventListener('click',e=>{const d=e.target.closest('[data-otp-detail]');if(d&&state.view==='otp')return openDetail(d);const h=e.target.closest('[data-sort]');if(h){const c=h.dataset.sort;state.sort={column:c,direction:state.sort.column===c&&state.sort.direction==='asc'?'desc':'asc'};render()}});el('reportOtpDetailSearch').addEventListener('input',()=>{clearTimeout(state.detailTimer);state.detailTimer=setTimeout(()=>loadDetail(1),350)});el('reportOtpDetailFooter').addEventListener('click',e=>{if(e.target.closest('#reportOtpDetailExport'))exportTsv(state.detail,'Detail_OTP');const p=e.target.closest('[data-detail-page]')?.dataset.detailPage;if(p)loadDetail(state.detailPage+(p==='next'?1:-1))})}
 async function init(){await initFilters();bind();bindCollectionDetail();load()}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
</script>
